//! CHM reader tests against tests/fixtures/chm (generated by tests/gen/ms.py;
//! all but partial_frame.chm extract identically with 7-Zip 26.04 per
//! tests/gen/ms_oracle.sh).

mod ms_common;
use ms_common::{crc, cut_points, expect, fixture, mutations};
use sediment_engine::chm_read::{ChmArchive, ChmError, ChmLimits};
use sediment_engine::extract_plan::EntryKind;

fn lim() -> ChmLimits {
    ChmLimits::default()
}

fn check(name: &str, expect_name: &str) {
    let bytes = fixture("chm", name);
    let chm = ChmArchive::parse(&bytes, lim()).unwrap();
    let exp = expect("chm", expect_name);
    assert_eq!(chm.entries().len(), exp.len(), "{name}: entry count");
    let all = chm.read_all();
    for (i, (e, x)) in chm.entries().iter().zip(&exp).enumerate() {
        assert_eq!(e.name, x.path.as_bytes(), "{name}: entry {i}");
        assert_eq!(e.is_dir(), x.dir);
        if x.dir {
            assert_eq!(e.length, 0);
            continue;
        }
        assert_eq!(e.length, x.size, "{name}: {} size", x.path);
        let d = chm.read(i).unwrap_or_else(|err| panic!("{name}: {}: {err:?}", x.path));
        assert_eq!(Some(crc(&d)), x.crc, "{name}: {} crc", x.path);
        assert_eq!(all[i].as_ref().unwrap(), &d, "{name}: read_all vs read");
    }
}

#[test]
fn multi_chunk_directory_with_index() {
    check("help.chm", "help.chm");
    let bytes = fixture("chm", "help.chm");
    let chm = ChmArchive::parse(&bytes, lim()).unwrap();
    assert_eq!(chm.version, 3);
    assert_eq!(chm.language, 0x409);
    let lzx = chm.lzx.as_ref().unwrap();
    assert_eq!(lzx.window_bits, 16);
    assert_eq!(lzx.reset_interval_frames, 2);
    assert!(lzx.uncompressed_len > 2 * 32768, "spans more than one reset interval");
    // more than one PMGL chunk was needed
    assert!(chm.entries().len() > 80);
    let i = chm.find(b"/index.html").unwrap();
    assert!(!chm.entries()[i].is_system());
    assert_eq!(chm.entries()[i].path, "index.html");
    assert_eq!(chm.entries()[i].section, 1);
    assert!(chm.entries()[chm.find(b"/#SYSTEM").unwrap()].is_system());
    assert!(chm.entries()[chm.find(b"::DataSpace/NameList").unwrap()].is_system());
    let d = chm.read(i).unwrap();
    assert!(d.starts_with(b"<html><body>") && d.ends_with(b"</body></html>"));
    let pe = chm.planned_entries();
    assert_eq!(pe[chm.find(b"/docs/").unwrap()].kind, EntryKind::Dir);
    assert_eq!(pe[i].path, b"index.html");
}

#[test]
fn single_chunk_window15_reset4() {
    check("small.chm", "small.chm");
    let bytes = fixture("chm", "small.chm");
    let chm = ChmArchive::parse(&bytes, lim()).unwrap();
    let lzx = chm.lzx.as_ref().unwrap();
    assert_eq!((lzx.window_bits, lzx.reset_interval_frames), (15, 4));
}

#[test]
fn exact_frame_multiple() {
    check("exact.chm", "exact.chm");
    let bytes = fixture("chm", "exact.chm");
    let chm = ChmArchive::parse(&bytes, lim()).unwrap();
    assert_eq!(chm.lzx.as_ref().unwrap().uncompressed_len, 65536);
}

